-- Baseline: registra todas as migrations existentes como já aplicadas
-- Rode este script UMA VEZ no banco de produção via psql ou terminal SQL do EasyPanel
-- Depois disso, `prisma migrate deploy` vai funcionar normalmente

CREATE TABLE IF NOT EXISTS "_prisma_migrations" (
  id VARCHAR(36) NOT NULL PRIMARY KEY,
  checksum VARCHAR(64) NOT NULL,
  finished_at TIMESTAMPTZ,
  migration_name VARCHAR(255) NOT NULL,
  logs TEXT,
  rolled_back_at TIMESTAMPTZ,
  started_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  applied_steps_count INTEGER NOT NULL DEFAULT 0
);

